import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Build the CUDA extension once
_tsmm_ext = load_inline(
    name="tsmm_ext",
    cpp_sources="",
    cuda_sources="""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda.h>
#include <cuda_runtime.h>
template <typename scalar_t>
__global__ void tsmm_kernel(const scalar_t* __restrict__ A,
                            const scalar_t* __restrict__ B,
                            scalar_t* __restrict__ C,
                            int64_t M, int64_t K, int64_t N) {
    // Each thread computes one C[row, col]
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    if (row < M && col < N) {
        scalar_t sum = 0;
        int64_t a_base = row * K;
        int64_t b_base = col;
        // Accumulate over K
        for (int64_t k = 0; k < K; ++k) {
            sum += A[a_base + k] * B[k * N + b_base];
        }
        C[row * N + col] = sum;
    }
}
torch::Tensor ts_matmul(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D tensors");
    TORCH_CHECK(A.size(1) == B.size(0),
                "Inner dimensions must match: A is (", A.size(0), ",", A.size(1),
                "), B is (", B.size(0), ",", B.size(1), ")");
    TORCH_CHECK(A.is_contiguous() && B.is_contiguous(),
                "A and B must be contiguous");
    TORCH_CHECK(A.scalar_type() == torch::kFloat32 && B.scalar_type() == torch::kFloat32,
                "Only float32 tensors are supported");
    const int64_t M = A.size(0);
    const int64_t K = A.size(1);
    const int64_t N = B.size(1);
    auto C = torch::empty({M, N}, A.options());
    if (M == 0 || K == 0 || N == 0) {
        return C; // nothing to do
    }
    const dim3 block(16, 16);
    const dim3 grid((N + block.x - 1) / block.x,
                    (M + block.y - 1) / block.y);
    const float* A_ptr = A.data_ptr<float>();
    const float* B_ptr = B.data_ptr<float>();
    float* C_ptr = C.data_ptr<float>();
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    tsmm_kernel<float><<<grid, block, 0, stream>>>(A_ptr, B_ptr, C_ptr, M, K, N);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return C;
}
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("ts_matmul", &ts_matmul, "Tall/Skinny Matrix Multiplication (CUDA)");
}
""",
    with_cuda=True,
    extra_cflags=["-O2", "-std=c++17"],
    extra_cuda_cflags=["-O2", "-std=c++17"]
)

class _TSMatMulFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        if not A.is_cuda or not B.is_cuda:
            raise RuntimeError("ModelNew requires CUDA tensors for A and B.")
        if A.dtype != torch.float32 or B.dtype != torch.float32:
            raise RuntimeError("ModelNew supports only float32 tensors.")
        if A.dim() != 2 or B.dim() != 2:
            raise RuntimeError("A and B must be 2D matrices.")
        if A.size(1) != B.size(0):
            raise RuntimeError(f"Inner dimensions must match: got {A.size()} and {B.size()}.")

        A_c = A.contiguous()
        B_c = B.contiguous()
        return _tsmm_ext.ts_matmul(A_c, B_c)

    @staticmethod
    def backward(ctx, grad_output):
        raise NotImplementedError("Backward is not implemented for ModelNew.")

class ModelNew(nn.Module):
    """
    ModelNew performs a single matrix multiplication C = A * B using a custom CUDA kernel.
    Expects:
      A: shape (M, K), CUDA float32 contiguous
      B: shape (K, N), CUDA float32 contiguous
    Returns:
      C: shape (M, N)
    """
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return _TSMatMulFunction.apply(A, B)

